from urllib.parse import quote


def _encode_component(value) -> str:
    """Percent-encode a single key or value per the module rules."""
    if value is True:
        text = "true"
    elif value is False:
        text = "false"
    else:
        text = str(value)
    # ``quote`` (unlike ``quote_plus``) writes a space as ``%20`` and, with an
    # empty ``safe`` set, leaves only ``-._~`` and alphanumerics unencoded.
    return quote(text, safe="")
